+        <section class="stats-panel">
+            <div class="stat-card">
+                <span class="stat-label">Total Tasks</span>
+                <span id="total-count" class="stat-value">0</span>
+            </div>
+            <div class="stat-card">
+                <span class="stat-label">Pending</span>
+                <span id="pending-count" class="stat-value">0</span>
+            </div>
+            <div class="stat-card">
+                <span class="stat-label">Completed</span>
+                <span id="completed-count" class="stat-value">0</span>
+            </div>
+        </section>
+
+        <section class="todo-list">
+            <ul id="todo-items" aria-label="Task list"></ul>
+            <p id="empty-state" class="empty-state">No tasks yet. Add one above!</p>
+        </section>
+    </main>
+
+    <script src="app.js"></script>
+</body>
+</html>--- a/training/level-3/L3-006-todo-dashboard/styles.css
